args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?maternalGrandmother ?mgLabel WHERE {
  VALUES ?person { dbr:Marie_Christine_Felizitas_of_Leiningen-Dagsburg-Falkenburg-Heidesheim }
  {
    ?person dbp:mother ?mother .
    { ?mother dbp:mother ?maternalGrandmother . }
    UNION
    { ?mother dbo:parent ?maternalGrandmother . }
  }
  UNION
  {
    ?person dbo:parent ?mother .
    { ?mother dbp:mother ?maternalGrandmother . }
    UNION
    { ?mother dbo:parent ?maternalGrandmother . }
  }
  OPTIONAL { ?maternalGrandmother rdfs:label ?mgLabel . FILTER(lang(?mgLabel) = "en") }
}

